import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String word = next();
        long k = nextLong();
        int n = word.length();
        char[] chars = new char[n];
        long[] counts = new long[n]; // stack of (character, consecutive count)
        int top = 0;
        for (int i = 0; i < n; i++) {
            char c = word.charAt(i);
            if (top > 0 && chars[top - 1] == c) {
                if (++counts[top - 1] == k) top--;
            } else {
                chars[top] = c;
                counts[top++] = 1;
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < top; i++)
            for (long j = 0; j < counts[i]; j++) sb.append(chars[i]);
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strings"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	word := nextToken()
	k := nextInt()
	type group struct {
		c     byte
		count int64
	}
	var st []group // (character, consecutive count)
	for i := 0; i < len(word); i++ {
		c := word[i]
		if len(st) > 0 && st[len(st)-1].c == c {
			st[len(st)-1].count++
			if st[len(st)-1].count == k {
				st = st[:len(st)-1]
			}
		} else {
			st = append(st, group{c, 1})
		}
	}
	var sb strings.Builder
	for _, g := range st {
		sb.WriteString(strings.Repeat(string(g.c), int(g.count)))
	}
	sb.WriteByte('\n')
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(sb.String())
}
